// Set the end of accessible data space (aka "the break") to ADDR.
// Returns zero on success and -1 for errors (with errno set).
//
//go:linkname Brk C.brk
func Brk(__addr unsafe.Pointer) c.Int

// Increase or decrease the end of accessible data space by DELTA bytes.
// If successful, returns the address the previous end of data space
// (i.e. the beginning of the new space, if DELTA > 0);
// returns (void *) -1 for errors (with errno set).
//
//go:linkname Sbrk C.sbrk
func Sbrk(__delta c.IntptrT) unsafe.Pointer

// Invoke `system call' number SYSNO, passing it the remaining arguments.
// This is completely system-dependent, and not often useful.
//
// In Unix, `syscall' sets `errno' for all errors and most calls return -1
// for errors; in many systems you cannot pass arguments or get return
// values for all system calls (`pipe', `fork', and `getppid' typically
// among them).
//
// In Mach, all system calls take normal arguments and always return an
// error code (zero for success).
//
//go:linkname Syscall C.syscall
func Syscall(__sysno c.Long, __llgo_va_list ...any) c.Long

// Synchronize at least the data part of a file with the underlying
// media.
//
//go:linkname Fdatasync C.fdatasync
func Fdatasync(__fildes c.Int) c.Int

// Structure describing file times.
type Utimbuf struct {
	Actime  c.Long
	Modtime c.Long
}

// Set the access and modification times of FILE to those given in
// FILE_TIMES.  If FILE_TIMES is NULL, set them to the current time.
//
//go:linkname Utime C.utime
func Utime(__file *c.Char, __file_times *Utimbuf) c.Int

const (
	EAGAIN     = 11
	F_GETFL    = 3
	F_SETFL    = 4
	O_ACCMODE  = 3
	O_CREAT    = 64
	O_NONBLOCK = 2048
	O_RDONLY   = 0
	O_RDWR     = 2
	O_TRUNC    = 512
	O_WRONLY   = 1
)
